from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    edge_counts = Counter()
    for c in range(w):
        if grid[0][c] != background: edge_counts[grid[0][c]] += 1
        if grid[h - 1][c] != background: edge_counts[grid[h - 1][c]] += 1
    for r in range(1, h - 1):
        if grid[r][0] != background: edge_counts[grid[r][0]] += 1
        if grid[r][w - 1] != background: edge_counts[grid[r][w - 1]] += 1
    boundary = edge_counts.most_common(1)[0][0]
    fill = next(v for v, _ in counts.most_common() if v not in (background, boundary))
    out = [row[:] for row in grid]
    rays = []
    for c in range(w):
        if grid[0][c] == boundary: rays.append((0, c, 1, 0))
        if grid[h - 1][c] == boundary: rays.append((h - 1, c, -1, 0))
    for r in range(h):
        if grid[r][0] == boundary: rays.append((r, 0, 0, 1))
        if grid[r][w - 1] == boundary: rays.append((r, w - 1, 0, -1))
    for r, c, dr, dc in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            v = grid[rr][cc]
            if v == boundary:
                break
            if v != background:
                out[rr][cc] = 4
                break
            out[rr][cc] = fill
            rr += dr
            cc += dc
    return out

